/*
 * Build sim/browser-bundle.js — the sim modules, loadable by a browser.
 *
 * ⚠️ WHY THIS EXISTS RATHER THAN SIX <script> TAGS. Classic scripts share ONE
 * global lexical scope, so two files both declaring `const API` at top level is
 * a SyntaxError that kills the page before a single pixel is drawn. The modules
 * collide on TWELVE identifiers — API, DEFAULTS, makeRng, step, run, P, C,
 * gauss, S_BINS, PHI_BINS, ANGLE_GENE, __node — because they were written as
 * CommonJS, where that is completely legal.
 *
 * So each module gets its own function scope and a `require` shim, which is
 * exactly what Node already does. The MODEL FILES ARE NOT TOUCHED: no dual
 * exports, no browser branches, nothing in sim/*.js that exists only for the
 * renderer. The alternative — editing six model files so a page can load them —
 * puts renderer concerns inside the science.
 *
 * The bundle is generated and committed, so the page works from file:// with no
 * server. tests/browser-bundle.test.js regenerates it and fails if the committed
 * copy has drifted, which is what stops a stale bundle silently rendering old
 * biology.
 */

const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
/* dependency order is irrelevant — require() resolves lazily — but keep it
 * readable and stable so the generated file has a stable diff */
const MODULES = [
  "placement",
  "packing",
  "carryover",
  "evolve",
  "deception",
  "ibm",
];
/* the globals the renderer reads */
const EXPOSE = {
  placement: "Placement",
  packing: "Packing",
  carryover: "Carryover",
  evolve: "Evolve",
  deception: "Deception",
  ibm: "IBM",
};

function build() {
  const parts = [];
  parts.push(`/* GENERATED by tools/build-browser-bundle.js — DO NOT EDIT.
 * Regenerate with:  node tools/build-browser-bundle.js
 * tests/browser-bundle.test.js fails if this drifts from sim/*.js. */
(function (global) {
  "use strict";
  const __defs = {};
  const __cache = {};
  function require(p) {
    const k = String(p).replace(/^\\.\\//, "").replace(/\\.js$/, "");
    if (k in __cache) return __cache[k];
    if (!(k in __defs)) throw new Error("browser-bundle: no module " + k);
    const module = { exports: {} };
    __cache[k] = module.exports;
    __defs[k](module, module.exports, require);
    __cache[k] = module.exports;
    return __cache[k];
  }
`);

  for (const m of MODULES) {
    const src = fs.readFileSync(path.join(ROOT, "sim", `${m}.js`), "utf8");
    parts.push(
      `  __defs[${JSON.stringify(m)}] = function (module, exports, require) {\n`,
    );
    parts.push(src);
    parts.push(`\n  };\n`);
  }

  for (const m of MODULES)
    parts.push(
      `  global[${JSON.stringify(EXPOSE[m])}] = require("./${m}.js");\n`,
    );

  parts.push(`})(typeof window !== "undefined" ? window : globalThis);\n`);
  return parts.join("");
}

const OUT = path.join(ROOT, "sim", "browser-bundle.js");

if (require.main === module) {
  fs.writeFileSync(OUT, build(), "utf8");
  console.log(`wrote ${path.relative(ROOT, OUT)} (${build().length} bytes)`);
}

module.exports = { build, OUT, MODULES, EXPOSE };
